        moveAllArmies(window->m_armies[0], window->m_armies[1]);
        for (long i = 0; i < armyGroup::ARMY_GROUP_SLOT_COUNT; ++i) {
            window->update(0, i);
            window->update(1, i);
        }
        window->updateButtons();
        window->drawWindow(
            1, WINDOW_ALL_WIDGETS_LOW, WINDOW_ALL_WIDGETS_HIGH);
